// user.module.ts
import { Global, Module } from '@nestjs/common';
import { UsersController } from './user.controller';
import { UserService } from './user.service';
import { UserRepository } from './user.repository';

@Global() // аккуратно: глобальные модули скрывают источники зависимостей
@Module({
  controllers: [UsersController],
  providers: [UserService, { provide: UserRepository, useClass: SqlUserRepository }],
  exports: [UserService],
})
export class UserModule {}

// 1) Глобальный интерсептор: тайминг + единый конверт ответа
@Injectable()
export class ResponseInterceptor implements NestInterceptor {
  intercept(ctx: ExecutionContext, next: CallHandler): Observable<unknown> {
    const started = Date.now();
    const req = ctx.switchToHttp().getRequest<Request & { id: string }>();
    return next.handle().pipe(
      map(data => ({ data, meta: { requestId: req.id, tookMs: Date.now() - started } })),
      catchError(err => throwError(() => err)),
    );
  }
}

// 2) Guard с ролями (RBAC)
@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private readonly reflector: Reflector) {}
  canActivate(ctx: ExecutionContext): boolean {
    const roles = this.reflector.getAllAndOverride<string[]>('roles', [
      ctx.getHandler(), ctx.getClass(),
    ]);
    if (!roles?.length) return true;
    const user = ctx.switchToHttp().getRequest().user as { roles: string[] } | undefined;
    return !!user && roles.some(r => user.roles.includes(r));
  }
}

// 3) Единый формат ошибки
@Catch()
export class AllExceptionsFilter implements ExceptionFilter {
  catch(exception: unknown, host: ArgumentsHost) {
    const res = host.switchToHttp().getResponse();
    const known = exception instanceof HttpException;
    const status = known ? exception.getStatus() : HttpStatus.INTERNAL_SERVER_ERROR;
    const payload = known ? exception.getResponse() : 'internal error';
    res.status(status).json({
      error: { status, message: payload, requestId: res.req.id, timestamp: new Date().toISOString() },
    });
  }
}

// config.validation.ts — конфигурация, которая валится на старте, а не в рантайме
const EnvSchema = z.object({
  NODE_ENV: z.enum(['development', 'test', 'production']),
  PORT: z.coerce.number().int().default(3000),
  DATABASE_URL: z.url(),
  KAFKA_BROKERS: z.string().transform(s => s.split(',')).pipe(z.array(z.string()).min(1)),
  JWT_SECRET: z.string().min(32),
});

// app.module.ts
ConfigModule.forRoot({ isGlobal: true, validate: (env) => EnvSchema.parse(env) });

// main.ts
const app = await NestFactory.create(AppModule, { bufferLogs: true });
app.enableShutdownHooks();               // SIGTERM -> onModuleDestroy -> закрытие пулов/консьюмеров
app.useGlobalPipes(new ValidationPipe({ whitelist: true, transform: true, forbidNonWhitelisted: true }));
app.useGlobalFilters(new AllExceptionsFilter());
app.useGlobalInterceptors(new ResponseInterceptor());
await app.listen(process.env.PORT ?? 3000);

// health: liveness (жив ли процесс) и readiness (готов ли принимать трафик)
TerminusModule.forRoot({ logger: ... }),
// в HealthController: DatabaseHealthIndicator + KafkaHealthIndicator + MemoryHealthIndicator

@Injectable()
export class OrderService {
  constructor(
    @InjectRepository(Order) private readonly repo: Repository<Order>,
    private readonly dataSource: DataSource,
    private readonly outbox: OutboxService,     // см. Модуль 6
  ) {}

  /** Денежные операции — только через транзакцию с явным уровнем изоляции. */
  async pay(orderId: string, amountCents: number, idemKey: string): Promise<Order> {
    return this.dataSource.transaction('READ COMMITTED', async (em) => {
      const order = await em.findOne(Order, {
        where: { id: orderId },
        lock: { mode: 'pessimistic_write' },   // SELECT ... FOR UPDATE
      });
      if (!order) throw new NotFoundException('order not found');
      if (order.status === 'paid') return order;      // идемпотентный повтор
      order.status = 'paid';
      order.paidAmountCents = amountCents;
      await em.save(order);
      await this.outbox.append(em, {          // событие пишем в той же транзакции
        type: 'order.paid.v1',
        aggregateId: order.id,
        payload: { orderId: order.id, amountCents },
        idempotencyKey: idemKey,
      });
      return order;
    });
  }
}

// main.ts — Kafka как транспорт микросервиса
app.connectMicroservice<MicroservicesOptions>({
  transport: Transport.KAFKA,
  options: {
    client: { clientId: 'orders', brokers: [process.env.KAFKA_BROKER!] },
    consumer: { groupId: 'orders-svc' },
    subscribe: { fromBeginning: false },
  },
});
await app.startAllMicroservices();

// orders.controller.ts — команда (request/response)
@MessagePattern('order.create')
async create(@Payload() dto: CreateOrderDto, @Ctx() ctx: KafkaContext): Promise<OrderView> {
  const { topic, partition, offset } = ctx.getMessage();
  const key = ctx.getMessage().key?.toString();
  return this.service.create(dto, { source: `${topic}[${partition}]@${offset}`, key });
}

// notifications.controller.ts — событие (fire-and-forget)
@EventPattern('order.paid.v1')
async onPaid(@Payload() event: OrderPaidEvent, @Ctx() ctx: KafkaContext) {
  await this.notifications.sendReceipt(event); // идемпотентно! см. Модуль 6
}
